package com.pipican.boss;
import java.util.*;import net.minecraft.core.particles.ParticleTypes;import net.minecraft.server.level.ServerLevel;import net.minecraft.sounds.SoundEvents;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.entity.player.Player;import net.minecraft.world.entity.projectile.Projectile;import net.minecraft.world.level.storage.ValueInput;import net.minecraft.world.level.storage.ValueOutput;import net.minecraft.world.phys.Vec3;
/** Locked luminous beams, harmonic wave bands, and shootable converging lantern rays. */
public final class LumynaraCombat{
 public static final String GAZE="luminous_gaze",WAVES="choral_waves",LANTERNS="abyssal_lanterns";private final RegionalBossEntity boss;private final RegionalCombatClock clock;private Vec3 origin=Vec3.ZERO,mark=Vec3.ZERO;private double heading;private List<Boolean> broken=List.of(false,false,false,false);private int phase=1,safeBand=0;
 public LumynaraCombat(RegionalBossEntity b){boss=b;var d=BossDesigns.require("lumynara_abyssal_oracle");clock=new RegionalCombatClock(Map.of(GAZE,time(d,0),WAVES,time(d,1),LANTERNS,time(d,2),"basic",new RegionalCombatClock.Timing(18,20,55)));}private static RegionalCombatClock.Timing time(BossDesigns.Design d,int i){var a=d.abilities().get(i);return new RegionalCombatClock.Timing(a.windup(),a.recovery(),a.cooldown());}
 public RegionalCombatClock clock(){return clock;}public int brokenLanterns(){return(int)broken.stream().filter(Boolean::booleanValue).count();}public int safeBand(){return safeBand;}public double safeRadius(){return safeBand==0?6.1:5.2;}public Vec3 lantern(int i){if(i<0||i>=4)throw new IndexOutOfBoundsException();double a=heading+i*Math.PI/2+(phase==2?.18:0);return origin.add(Math.cos(a)*7,0,Math.sin(a)*7);}public Vec3 gazePoint(int n){return ray(0).get(Math.clamp(n,0,ray(0).size()-1));}public Vec3 wavePoint(double r,int a){double t=Math.toRadians(a);return origin.add(Math.cos(t)*r,0,Math.sin(t)*r);}public Vec3 lanternRayPoint(int i,int n){return rayFrom(lantern(i)).get(Math.clamp(n,0,rayFrom(lantern(i)).size()-1));}
 public boolean begin(String id,LivingEntity t){if(t==null||!t.isAlive()||!boss.insideArena(t.position())||!clock.begin(id))return false;origin=boss.position();mark=t.position();heading=Math.atan2(mark.z-origin.z,mark.x-origin.x);phase=clock.phase();if(phase==2){safeBand=(safeBand+1)%2;heading-=.12;boss.playSound(SoundEvents.AMETHYST_BLOCK_CHIME,1.15f,.72f);}if(id.equals(LANTERNS))broken=List.of(false,false,false,false);return true;}
 private List<Vec3> ray(int echo){var p=new ArrayList<Vec3>();double a=heading+(echo==1?.34:echo==-1?-.34:0);for(int n=2;n<=15;n++){Vec3 q=origin.add(Math.cos(a)*n,0,Math.sin(a)*n);if(boss.insideArena(q))p.add(q);}return p;}
 private List<Vec3> rayFrom(Vec3 start){var p=new ArrayList<Vec3>();Vec3 delta=origin.subtract(start);for(int n=0;n<=20;n++){Vec3 q=start.add(delta.scale(n/20.0));if(boss.insideArena(q))p.add(q);}return p;}
 private List<Vec3> circle(double radius){var p=new ArrayList<Vec3>();for(int a=0;a<360;a+=8){double t=Math.toRadians(a);Vec3 q=origin.add(Math.cos(t)*radius,0,Math.sin(t)*radius);if(boss.insideArena(q))p.add(q);}return p;}
 public void tick(ServerLevel l){String id=clock.active();if(id.equals(LANTERNS)&&!clock.resolved())checkLanterns(l);if(!id.isEmpty()&&!clock.resolved()&&clock.remaining()%5==0)telegraph(l,id);if(id.isEmpty()){clock.tick();return;}String impact=clock.tick();if(impact.isEmpty())return;switch(impact){case GAZE->{strike(l,ray(0),.66f);if(phase==2)strike(l,ray(1),.32f);boss.playSound(SoundEvents.BEACON_ACTIVATE,1.05f,.7f);}case WAVES->{strike(l,circle(safeBand==0?3.7:4.4),.48f);strike(l,circle(safeBand==0?8.6:7.8),.48f);boss.playSound(SoundEvents.CONDUIT_AMBIENT,1.1f,.7f);}case LANTERNS->{for(int i=0;i<4;i++)if(!broken.get(i))strike(l,rayFrom(lantern(i)),.44f);boss.playSound(SoundEvents.GENERIC_EXPLODE.value(),1f,.75f);}case "basic"->strike(l,List.of(mark),.68f);default->{}}}
 private void checkLanterns(ServerLevel l){var n=new ArrayList<>(broken);for(int i=0;i<4;i++)if(!n.get(i)){Vec3 p=lantern(i);var shots=l.getEntitiesOfClass(Projectile.class,new net.minecraft.world.phys.AABB(p.add(-1,-1,-1),p.add(1,1.5,1)),Projectile::isAlive);if(!shots.isEmpty()){n.set(i,true);shots.forEach(Projectile::discard);l.sendParticles(ParticleTypes.POOF,p.x,p.y,p.z,14,.25,.2,.25,.02);}}broken=List.copyOf(n);}
 private void telegraph(ServerLevel l,String id){if(id.equals(GAZE)){for(int echo=-1;echo<=(phase==2?1:0);echo++)for(Vec3 p:ray(echo))if((int)(p.x+p.z)%3==0)l.sendParticles(ParticleTypes.END_ROD,p.x,p.y+.2,p.z,1,.025,.035,.025,0);Vec3 eye=origin.add(Math.cos(heading)*.8,1.8,Math.sin(heading)*.8);l.sendParticles(ParticleTypes.GLOW,eye.x,eye.y,eye.z,6,.12,.12,.12,0);}else if(id.equals(WAVES)){for(double r:new double[]{safeBand==0?3.7:4.4,safeBand==0?8.6:7.8})for(Vec3 p:circle(r))if((int)(p.x+p.z)%4==0)l.sendParticles(ParticleTypes.SONIC_BOOM,p.x,p.y+.1,p.z,1,0,0,0,0);}else for(int i=0;i<4;i++){Vec3 p=lantern(i);l.sendParticles(broken.get(i)?ParticleTypes.POOF:ParticleTypes.GLOW,p.x,p.y+.3,p.z,9,.2,.2,.2,0);if(!broken.get(i))for(Vec3 q:rayFrom(p))if((int)(q.x+q.z)%3==0)l.sendParticles(ParticleTypes.END_ROD,q.x,q.y+.1,q.z,1,.02,.03,.02,0);}}
 private void strike(ServerLevel l,List<Vec3> points,float scale){for(Player p:l.getEntitiesOfClass(Player.class,boss.getBoundingBox().inflate(28),q->q.isAlive()&&!q.isCreative()&&!q.isSpectator()&&boss.insideArena(q.position())))if(points.stream().anyMatch(q->Math.abs(q.y-p.getY())<3&&q.distanceToSqr(p.position())<1.8*1.8))p.hurtServer(l,boss.damageSources().mobAttack(boss),(float)(boss.getAttributeValue(Attributes.ATTACK_DAMAGE)*scale));}
 public boolean updatePhase(float hp,float max){boolean c=clock.updatePhase(hp,max);if(c)phase=2;return c;}public void save(ValueOutput o){clock.save(o);o.store("LumynaraOrigin",Vec3.CODEC,origin);o.store("LumynaraMark",Vec3.CODEC,mark);o.store("LumynaraBroken",com.mojang.serialization.Codec.BOOL.listOf(),broken);o.putDouble("LumynaraHeading",heading);o.putInt("LumynaraPhase",phase);o.putInt("LumynaraSafeBand",safeBand);}public void load(ValueInput i){clock.load(i);origin=i.read("LumynaraOrigin",Vec3.CODEC).orElse(Vec3.ZERO);mark=i.read("LumynaraMark",Vec3.CODEC).orElse(Vec3.ZERO);broken=i.read("LumynaraBroken",com.mojang.serialization.Codec.BOOL.listOf()).orElse(List.of(false,false,false,false)).stream().limit(4).toList();if(broken.size()<4){var n=new ArrayList<>(broken);while(n.size()<4)n.add(false);broken=List.copyOf(n);}heading=i.getDoubleOr("LumynaraHeading",0);phase=clock.phase();safeBand=Math.floorMod(i.getIntOr("LumynaraSafeBand",0),2);}
}
